mapper.sql:
SELECT T.ID, T.USER_ID, T.GOODS_ID, T.ADD_TIME, T.REFERRER, U.NICKNAME FROM mall_footprint T LEFT JOIN WX_USER U ON T.USER_ID = U.ID WHERE 1=1
AND T.ID = #{params.id}
AND T.USER_ID = #{params.userId}
AND T.NAME LIKE CONCAT('%', #{params.name}, '%')

mapper.select:
select f.id,f.user_id,f.goods_id,f.add_time add_time,f.referrer, g.name as name, g.list_pic_url, g.goods_brief as goods_brief, g.retail_price as retail_price, u.nickname as nickname,u.head_img_url as avatar from mall_footprint f left join mall_goods g on f.goods_id = g.id left join WX_USER u on u.id = f.user_id
u.id is not null and g.is_delete = 0
and f.user_id = #{userId}
and f.referrer = #{referrer}
order by f.id desc
limit #{offset}, #{limit}

mapper.delete:
DELETE f FROM mall_footprint f
JOIN mall_footprint chosen ON chosen.goods_id=f.goods_id AND chosen.user_id=f.user_id
WHERE chosen.id=#{footprintId} AND chosen.user_id=#{userId}
